<script setup lang="ts">
import { ref,computed,onMounted } from 'vue'
import { api,json,downloadFile } from '../../api/client'
import { dateInput } from '../../utils/formatDate'
import { useAuth } from '../../stores/auth'
interface Template {id:string;name:string;group:string;fields:string[];body:string}
interface Salary {currency:string;increase:string;years:number;rows:{role:string;amount:string}[]}
interface Draft {id?:number;template:string;title:string;body:string;salary:Salary|null}
const auth=useAuth(),templates=ref<Template[]>([]),profile=ref<Record<string,string>>({}),fields=ref<Record<string,string>>({}),selected=ref(''),draft=ref<Draft|null>(null),saved=ref<{id:number;title:string;template:string}[]>([]),page=ref(1),last=ref(1),busy=ref(false),error=ref(''),notice=ref(''),showProfile=ref(false),dirty=ref(false),currencies=ref<{code:string;name:string;minor_units:number}[]>([])
const template=computed(()=>templates.value.find(t=>t.id===selected.value))
function label(s:string){return s.split('_').map(w=>w[0]?.toUpperCase()+w.slice(1)).join(' ')}
function discard(){return !dirty.value||window.confirm('Discard the unsaved changes to this document?')}
async function run(action:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function list(n=1){const r=await api<{data:typeof saved.value;last_page:number}>('/business-documents?page='+n);saved.value=r.data;page.value=n;last.value=r.last_page}
onMounted(()=>run(async()=>{const s=await api<{templates:Template[];profile:Record<string,string>}>('/business-documents/setup');templates.value=s.templates;profile.value=s.profile;currencies.value=await api('/currencies');await list()}))
function choose(t:Template){if(!discard())return;selected.value=t.id;draft.value=null;dirty.value=false;fields.value={document_date:dateInput()}}
function create(){if(!template.value)return;const values={...profile.value,...fields.value,document_date:fields.value.document_date||dateInput()};draft.value={template:template.value.id,title:template.value.name,body:template.value.body.replace(/{{(\w+)}}/g,(_,key:string)=>values[key as keyof typeof values]||'['+label(key)+']'),salary:template.value.id==='salary-structure'?{currency:auth.user?.business.currency||'NGN',increase:'0',years:5,rows:[{role:'',amount:'0'}]}:null};dirty.value=true;notice.value='Review and edit the wording below, then save before downloading.'}
async function save(){await run(async()=>{draft.value=await api<Draft>('/business-documents'+(draft.value?.id?'/'+draft.value.id:''),json(draft.value?.id?'PUT':'POST',draft.value));dirty.value=false;notice.value='Document saved privately.';await list()})}
async function open(id:number){if(!discard())return;await run(async()=>{draft.value=await api<Draft>('/business-documents/'+id);selected.value=draft.value.template;dirty.value=false})}
async function remove(){if(!draft.value?.id||!window.confirm('Permanently delete this saved document?'))return;await run(async()=>{await api('/business-documents/'+draft.value!.id,{method:'DELETE'});draft.value=null;dirty.value=false;await list();notice.value='Document deleted.'})}
async function download(format:string){await run(async()=>{await downloadFile('/business-documents/'+draft.value!.id+'/download/'+format,'business-document-'+draft.value!.id+'.'+format)})}
async function saveProfile(){await run(async()=>{profile.value=await api('/business-documents/profile',json('PUT',profile.value));notice.value='Company profile saved. Existing documents keep their saved wording and company details.'})}
const forecast=computed(()=>{const s=draft.value?.salary;if(!s)return null;const digits=currencies.value.find(c=>c.code===s.currency)?.minor_units??2;const factor=10n**BigInt(digits);const rate=Number(s.increase),years=Number(s.years);if(!Number.isFinite(rate)||rate<0||rate>100||!Number.isInteger(years)||years<1||years>10||!/^\d{1,3}(\.\d{1,2})?$/.test(s.increase))return null;const rateInt=BigInt(Math.round(rate*100));const totals=Array<bigint>(years).fill(0n);try{const rows=s.rows.map(row=>{if(!/^\d{1,9}(\.\d{1,4})?$/.test(row.amount))throw Error();const [a,b='']=row.amount.split('.');if(b.length>digits)throw Error();let minor=BigInt(a!)*factor+BigInt(b.padEnd(digits,'0')||'0');const values=Array.from({length:years},(_,y)=>{if(y)minor=(minor*(10000n+rateInt)+5000n)/10000n;if(minor>1000000000000n)throw Error();totals[y]=totals[y]!+minor;if(totals[y]!>50000000000000n)throw Error();return minor});return {role:row.role,values}});const fmt=(v:bigint)=>new Intl.NumberFormat(undefined,{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(Number(v)/Number(factor));return {rows,totals,fmt}}catch{return null}})
</script>
<template>
<div class="page-heading"><div><h1>Business documents</h1><p class="muted">Company templates for recruitment, employment, onboarding and salary planning.</p></div><button class="button secondary" @click="showProfile=!showProfile">Company profile</button></div>
<p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
<section v-if="showProfile" class="panel form-panel spaced"><h2>Your company definition</h2><p class="muted">Used for new documents. This profile does not change your invoice settings.</p><form class="form-grid" @submit.prevent="saveProfile"><label v-for="(_,key) in profile" :key="key">{{ label(String(key)) }}<textarea v-model="profile[key]" :required="key==='company_name'" maxlength="3000" rows="2"/></label><button class="button primary" :disabled="busy">Save company profile</button></form></section>
<section class="panel form-panel spaced"><h2>Choose a document</h2><div class="document-catalog"><button v-for="t in templates" :key="t.id" class="button secondary" :class="{chosen:selected===t.id}" :aria-pressed="selected===t.id" :disabled="busy" @click="choose(t)">{{ t.name }}<small>{{ t.group }}</small></button></div></section>
<section v-if="template&&!draft" class="panel form-panel spaced"><h2>{{ template.name }}</h2><p class="muted">Fill what you know. Missing details are marked in square brackets for you to complete in the editor.</p><form class="form-grid" @submit.prevent="create"><label v-for="key in template.fields" :key="key">{{ label(key) }}<textarea v-model="fields[key]" maxlength="3000" rows="2"/></label><button class="button primary">Prepare editable draft</button></form></section>
<section v-if="draft" class="panel form-panel spaced"><h2>{{ draft.id?'Edit saved document':'New draft' }}</h2><form @submit.prevent="save" @input="dirty=true"><label>Document title<input v-model="draft.title" maxlength="160" required></label><label class="spaced">Document wording<textarea class="document-editor" v-model="draft.body" maxlength="30000" rows="22" required/></label>
<template v-if="draft.salary"><div class="form-grid spaced"><label>Currency<select v-model="draft.salary.currency"><option v-for="c in currencies" :key="c.code" :value="c.code">{{ c.code }} — {{ c.name }}</option></select></label><label>Annual increase (%)<input v-model="draft.salary.increase" type="number" min="0" max="100" step="0.01" required></label><label>Years<input v-model.number="draft.salary.years" type="number" min="1" max="10" required></label></div><p class="muted">Amounts per role per pay period. The increase is a planning assumption. Totals assume one employee per role.</p><div v-for="(row,i) in draft.salary.rows" :key="i" class="salary-inputs spaced"><label>Role<input v-model="row.role" required maxlength="120"></label><label>Starting amount<input v-model="row.amount" inputmode="decimal" required></label><button class="button secondary" type="button" :disabled="draft.salary.rows.length===1" @click="draft.salary.rows.splice(i,1);dirty=true">Remove role</button></div><button class="button secondary spaced" type="button" :disabled="draft.salary.rows.length>=50" @click="draft.salary.rows.push({role:'',amount:'0'});dirty=true">Add role</button><div v-if="forecast" class="table-wrap spaced"><table><thead><tr><th>Role</th><th v-for="(_,y) in forecast.totals" :key="y">Year {{ y+1 }}</th></tr></thead><tbody><tr v-for="(row,i) in forecast.rows" :key="i"><td>{{ row.role||'Role' }}</td><td v-for="(v,y) in row.values" :key="y">{{ forecast.fmt(v) }}</td></tr><tr><th>Total ({{ draft.salary.currency }})</th><th v-for="(v,y) in forecast.totals" :key="y">{{ forecast.fmt(v) }}</th></tr></tbody></table></div><p v-else class="error">Check the amounts, currency precision, increase and year limits.</p></template>
<div class="document-actions spaced"><button class="button primary" :disabled="busy||!!draft.salary&&!forecast">{{ busy?'Working…':'Save document' }}</button><button v-for="format in (draft.salary?['pdf','docx','xlsx']:['pdf','docx'])" :key="format" type="button" class="button secondary" :disabled="busy||!draft.id||dirty" @click="download(format)">Download {{ format.toUpperCase() }}</button><button v-if="draft.id" type="button" class="button secondary" :disabled="busy" @click="remove">Delete document</button></div><p v-if="dirty" class="muted">Save your changes to enable downloads.</p></form><p class="muted spaced">These are editable starting templates. Review employment terms and agreements for your business and applicable law before use. Generating a document does not send it, sign it, or carry out an employment action.</p></section>
<section class="panel form-panel spaced"><h2>Saved documents</h2><p class="muted">Private to this business. Available to its owners and admins.</p><p v-if="!saved.length">No saved documents yet.</p><ul class="saved-documents"><li v-for="d in saved" :key="d.id"><button class="button secondary" :disabled="busy" @click="open(d.id)">{{ d.title }}</button></li></ul><div class="document-actions"><button class="button secondary" :disabled="busy||page===1" @click="run(()=>list(page-1))">Previous</button><span>Page {{ page }} of {{ last }}</span><button class="button secondary" :disabled="busy||page>=last" @click="run(()=>list(page+1))">Next</button></div></section>
</template>
<style scoped>
.document-catalog{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(240px,100%),1fr));gap:12px}.document-catalog button{display:flex;align-items:flex-start;flex-direction:column;text-align:left;white-space:normal;height:auto}.document-catalog small{font-size:12px;opacity:.7}.chosen{outline:2px solid var(--primary,#107269)}.document-editor{font-family:inherit;line-height:1.6;min-height:400px;width:100%;resize:vertical}.document-actions,.salary-inputs{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.salary-inputs label{flex:1;min-width:160px}.saved-documents{list-style:none;padding:0;display:flex;flex-wrap:wrap;gap:10px}.saved-documents button{white-space:normal;overflow-wrap:anywhere}.table-wrap{max-width:100%;overflow:auto}label{display:block}section{min-width:0}
</style>
